def MSE(X,Y,W,bias):
    n = len(Y)
    y_pred = X.dot(W) + bias
    return (1/(2*n)) * (np.sum((y_pred - Y)**2))

def gradw(x,y,W,bias):
    n = len(y)
    y_pred = x.dot(W) + bias
    return (1/n) * ((x.T).dot(y_pred - y))

def gradb(x,y,W,bias):
    n = len(y)
    y_pred = x.dot(W) + bias
    return (1/n) * np.sum(y_pred - y)
